from pathlib import Path
import json,re

APP=Path('src/App.jsx')
CSS=Path('src/styles.css')
app=APP.read_text(encoding='utf-8')
css=CSS.read_text(encoding='utf-8')

old=" const products=<ProductRanking lines={bi.lines} articles={bi.articles} costMap={bi.costMap} onCostSaved={load}/>;"
new=" const products=<ProductIntelligence tickets={bi.tickets} lines={bi.lines} previousTickets={previous.tickets||[]} previousLines={previous.lines||[]} articles={bi.articles} costMap={bi.costMap} range={r} onCostSaved={load}/>;"
if old not in app and new not in app:
    raise SystemExit('ProductRanking invocation not found')
app=app.replace(old,new,1)

marker='function ProductRanking({lines,articles,costMap,onCostSaved}){'
if 'function ProductIntelligence(' not in app:
    if marker not in app:
        raise SystemExit('ProductRanking marker not found')
    component=r'''function ProductIntelligence({tickets,lines,previousTickets,previousLines,articles,costMap,range,onCostSaved}){
 const[query,setQuery]=useState('');
 const[selectedId,setSelectedId]=useState('');
 const[metric,setMetric]=useState('qty');
 const[detail,setDetail]=useState(null);
 const[costDraft,setCostDraft]=useState('');
 const[priceDraft,setPriceDraft]=useState('');
 const[targetMargin,setTargetMargin]=useState('60');
 const[saving,setSaving]=useState(false);
 const norm=v=>String(v||'').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 const currentRank=useMemo(()=>productRank(lines,'qty',articles),[lines,articles]);
 const candidates=useMemo(()=>{
  const m=new Map();
  articles?.forEach?.((v,k)=>{const code=String(k||'').trim();const name=String(v?.name||code).trim();if(code||name)m.set(code||`name:${norm(name)}`,{id:code||`name:${norm(name)}`,code,name,family:v?.family||'',qty:0,total:0,ticketCount:0})});
  currentRank.forEach(p=>{const id=p.code||`name:${norm(p.name)}`;m.set(id,{...m.get(id),...p,id})});
  return [...m.values()].sort((a,b)=>(b.qty||0)-(a.qty||0)||String(a.name).localeCompare(String(b.name),'es'));
 },[articles,currentRank]);
 const filtered=useMemo(()=>{const q=norm(query);return (q?candidates.filter(x=>norm(`${x.name} ${x.code}`).includes(q)):candidates.filter(x=>Number(x.qty||0)>0)).slice(0,30)},[candidates,query]);
 useEffect(()=>{if(!selectedId&&filtered[0])setSelectedId(filtered[0].id)},[filtered,selectedId]);
 const selected=candidates.find(x=>x.id===selectedId)||filtered[0]||null;
 const matchesLine=(l,p)=>{if(!p)return false;const code=String(l.articulo||'').trim();if(p.code&&code)return code===String(p.code);return norm(l.descripcion||l.nombre)===norm(p.name)};
 const ticketInfo=useMemo(()=>{const m=new Map();(tickets||[]).forEach(t=>m.set(String(t.cab_id||t.id),t));return m},[tickets]);
 const prevTicketInfo=useMemo(()=>{const m=new Map();(previousTickets||[]).forEach(t=>m.set(String(t.cab_id||t.id),t));return m},[previousTickets]);
 const selectedLines=useMemo(()=>selected?(lines||[]).filter(l=>matchesLine(l,selected)):[],[lines,selected]);
 const prevSelectedLines=useMemo(()=>selected?(previousLines||[]).filter(l=>matchesLine(l,selected)):[],[previousLines,selected]);
 const calcStats=(rows,map)=>{let qty=0,revenue=0;const ticketsSet=new Set();const byDay=new Map(),byHour=new Map();rows.forEach(l=>{const q=Math.abs(Number(l.cantidad||0)),r=Number(l.importe||0);qty+=q;revenue+=r;if(l.cab_id)ticketsSet.add(String(l.cab_id));const t=map.get(String(l.cab_id||''));const raw=t?.hora||t?.created_at||l.fecha||l.hora;const d=raw?String(raw).slice(0,10):'';if(d){const x=byDay.get(d)||{date:d,qty:0,revenue:0};x.qty+=q;x.revenue+=r;byDay.set(d,x)}if(raw){const h=String(new Date(raw).getHours()).padStart(2,'0')+':00';byHour.set(h,(byHour.get(h)||0)+q)}});return {qty,revenue,tickets:ticketsSet.size,avg:qty?revenue/qty:0,days:[...byDay.values()].sort((a,b)=>a.date.localeCompare(b.date)),hours:[...byHour.entries()].map(([hour,qty])=>({hour,qty})).sort((a,b)=>a.hour.localeCompare(b.hour))}};
 const stats=useMemo(()=>calcStats(selectedLines,ticketInfo),[selectedLines,ticketInfo]);
 const prev=useMemo(()=>calcStats(prevSelectedLines,prevTicketInfo),[prevSelectedLines,prevTicketInfo]);
 const info=selected?.code?costMap?.get?.(String(selected.code)):null;
 const configured=Boolean(info&&!info.excluded&&info.cost!==null&&Number.isFinite(Number(info.cost)));
 const unitCost=configured?Number(info.cost):Math.max(0,stats.avg/3);
 const currentProfit=(stats.avg-unitCost)*stats.qty;
 const currentMargin=stats.revenue?currentProfit/stats.revenue*100:0;
 useEffect(()=>{if(selected){setCostDraft(String(Number(unitCost||0).toFixed(4)));setPriceDraft(String(Number(stats.avg||0).toFixed(2))) }},[selectedId,unitCost,stats.avg]);
 const pct=(a,b)=>b?((a-b)/Math.abs(b))*100:(a?100:0);
 const qtyChange=pct(stats.qty,prev.qty),salesChange=pct(stats.revenue,prev.revenue),profitPrev=(prev.avg-unitCost)*prev.qty,profitChange=pct(currentProfit,profitPrev);
 const newCost=Math.max(0,Number(String(costDraft).replace(',','.'))||0),newPrice=Math.max(0,Number(String(priceDraft).replace(',','.'))||0);
 const simulatedRevenue=newPrice*stats.qty,simulatedProfit=(newPrice-newCost)*stats.qty,simulatedMargin=simulatedRevenue?simulatedProfit/simulatedRevenue*100:0,impact=simulatedProfit-currentProfit;
 const unitNewMargin=newPrice-newCost,breakEvenQty=unitNewMargin>0?Math.max(0,currentProfit/unitNewMargin):0,maxLossPct=stats.qty&&unitNewMargin>0?Math.max(0,(1-breakEvenQty/stats.qty)*100):0;
 const target= Math.min(95,Math.max(1,Number(targetMargin)||60));
 const targetPrice=newCost/(1-target/100);
 const associated=useMemo(()=>{if(!selected)return[];const cab=new Set(selectedLines.map(l=>String(l.cab_id||'')).filter(Boolean));return productRank((lines||[]).filter(l=>cab.has(String(l.cab_id||''))&&!matchesLine(l,selected)),'qty',articles).slice(0,6)},[selected,selectedLines,lines,articles]);
 const recommendation=(()=>{if(!selected)return 'Selecciona un producto para comenzar.';if(!stats.qty)return 'No hay ventas de este producto en el periodo seleccionado. Amplía el rango para obtener una recomendación basada en datos.';if(!configured)return 'Prioridad: confirma el coste real. Ahora se está usando la regla provisional de 1/3 del PVP, por lo que cualquier decisión de precio debe tomarse con cautela.';if(currentMargin<45)return `Margen bajo (${currentMargin.toFixed(1)}%). Antes de bajar precio, revisa coste y simula un PVP cercano a ${money(targetPrice)} para aproximarte al ${target.toFixed(0)}% de margen.`;if(qtyChange<-15&&currentMargin>60)return `Las unidades han caído ${Math.abs(qtyChange).toFixed(1)}% frente al periodo anterior aunque el margen es alto. Evitaría una subida agresiva hasta comprobar si la caída se mantiene.`;if(qtyChange>10&&currentMargin<60)return `El producto gana volumen (+${qtyChange.toFixed(1)}%) pero el margen es mejorable. Es buen candidato para probar una subida pequeña y medir el efecto.`;return `El producto mantiene un margen de ${currentMargin.toFixed(1)}% y ${stats.qty.toFixed(1)} unidades en el periodo. Usa el simulador para valorar precio/coste sin asumir cambios de demanda.`})();
 async function saveCost(){if(!selected?.code)return alert('Este producto no tiene código NUMIER para guardar el coste.');if(!Number.isFinite(newCost)||newCost<0)return alert('Coste no válido');setSaving(true);const result=await persistArticleCost(selected.code,newCost,'Actualizado desde Inteligencia de Producto 5.3');setSaving(false);if(result.error)alert('Coste guardado localmente, pero no se pudo sincronizar: '+result.error.message);else alert('Coste guardado. Se recalcularán los módulos económicos.');if(onCostSaved)await onCostSaved()}
 const open=(title,rows)=>setDetail({title,rows});
 const kpi=(title,value,small,rows)=><button type="button" className="card productIntelKpi" onClick={()=>open(title,rows)}><span>{title}</span><b>{value}</b><small>{small} · ver detalle ›</small></button>;
 const maxDay=Math.max(1,...stats.days.map(d=>metric==='qty'?d.qty:metric==='revenue'?d.revenue:((d.revenue-(unitCost*d.qty)))));
 return <div className="productIntelligence53">
  <section className="card productIntelSearch"><div><span className="sectionEyebrow">INTELIGENCIA DE PRODUCTO 5.3</span><h2>Busca, compara y simula decisiones</h2><p>El periodo es el seleccionado arriba: <b>{range?.label||'periodo actual'}</b>.</p></div><label>Buscar producto por nombre o código<input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Ej. cerveza, café, 00317…"/></label><div className="productIntelResults">{filtered.map(p=><button type="button" key={p.id} className={selected?.id===p.id?'active':''} onClick={()=>setSelectedId(p.id)}><span><b>{p.name}</b><small>{p.code||'Sin código'}{p.family?` · ${p.family}`:''}</small></span><em>{Number(p.qty||0).toFixed(1)} uds.</em></button>)}</div></section>
  {selected&&<><section className="card productIntelHero"><div><span className="sectionEyebrow">PRODUCTO SELECCIONADO</span><h2>{selected.name}</h2><p>{selected.code?`Código ${selected.code} · `:''}{stats.tickets} tickets · PVP medio real {money(stats.avg)}</p></div>{!configured&&<div className="quickCostNotice">Coste provisional: <b>1/3 del PVP</b>. Confírmalo antes de tomar decisiones definitivas.</div>}</section>
  <div className="grid productIntelKpis">{kpi('Unidades vendidas',stats.qty.toFixed(2),`${qtyChange>=0?'+':''}${qtyChange.toFixed(1)}% vs anterior`,[['Periodo',range?.label||'Actual'],['Unidades',stats.qty.toFixed(2)],['Anterior',prev.qty.toFixed(2)]])}{kpi('Facturación',money(stats.revenue),`${salesChange>=0?'+':''}${salesChange.toFixed(1)}% vs anterior`,[['Facturación',money(stats.revenue)],['Anterior',money(prev.revenue)],['PVP medio',money(stats.avg)]])}{kpi('Beneficio producto',money(currentProfit),`${profitChange>=0?'+':''}${profitChange.toFixed(1)}% vs anterior`,[['Ventas',money(stats.revenue)],['Coste producto',`− ${money(unitCost*stats.qty)}`],['Beneficio',money(currentProfit)]])}{kpi('Margen',`${currentMargin.toFixed(1)}%`,configured?'Coste configurado':'Coste provisional 1/3',[['PVP medio',money(stats.avg)],['Coste unidad',money(unitCost)],['Margen unidad',money(stats.avg-unitCost)]])}{kpi('Tickets',String(stats.tickets),stats.tickets?`${(stats.qty/stats.tickets).toFixed(2)} uds./ticket`:'Sin tickets',[['Tickets',stats.tickets],['Unidades',stats.qty.toFixed(2)],['Uds./ticket',stats.tickets?(stats.qty/stats.tickets).toFixed(2):'0']])}</div>
  <section className="card productIntelChart"><div className="row between"><div><h2>📈 Evolución del producto</h2><p className="mutedText">Pulsa una barra para ver el detalle del día.</p></div><div className="row wrap"><button className={metric==='qty'?'active':''} onClick={()=>setMetric('qty')}>Unidades</button><button className={metric==='revenue'?'active':''} onClick={()=>setMetric('revenue')}>Facturación</button><button className={metric==='profit'?'active':''} onClick={()=>setMetric('profit')}>Beneficio</button></div></div><div className="productIntelBars">{stats.days.map(d=>{const val=metric==='qty'?d.qty:metric==='revenue'?d.revenue:d.revenue-unitCost*d.qty;return <button type="button" key={d.date} onClick={()=>open(fmtDate(d.date),[['Unidades',d.qty.toFixed(2)],['Facturación',money(d.revenue)],['Beneficio producto',money(d.revenue-unitCost*d.qty)]])}><span>{new Date(d.date+'T12:00:00').toLocaleDateString('es-ES',{day:'2-digit',month:'2-digit'})}</span><i style={{height:`${Math.max(6,Math.abs(val)/maxDay*100)}%`}}></i><b>{metric==='qty'?d.qty.toFixed(1):money(val)}</b></button>})}</div>{!stats.days.length&&<p>No hay ventas en el periodo seleccionado.</p>}</section>
  <section className="grid productIntelCompare"><button className="card productIntelDecisionCard" onClick={()=>open('Comparativa equivalente',[['Unidades actuales',stats.qty.toFixed(2)],['Unidades anteriores',prev.qty.toFixed(2)],['Variación',`${qtyChange>=0?'+':''}${qtyChange.toFixed(1)}%`],['Facturación actual',money(stats.revenue)],['Facturación anterior',money(prev.revenue)],['Beneficio actual',money(currentProfit)],['Beneficio anterior',money(profitPrev)]])}><span className="sectionEyebrow">COMPARATIVA</span><h2>Periodo actual vs anterior</h2><p>Unidades <b>{qtyChange>=0?'+':''}{qtyChange.toFixed(1)}%</b> · ventas <b>{salesChange>=0?'+':''}{salesChange.toFixed(1)}%</b> · beneficio <b>{profitChange>=0?'+':''}{profitChange.toFixed(1)}%</b></p><em>Ver desglose ›</em></button><button className="card productIntelDecisionCard" onClick={()=>open('Horarios de venta',stats.hours.map(x=>[x.hour,`${x.qty.toFixed(2)} uds.`]))}><span className="sectionEyebrow">CUÁNDO SE VENDE</span><h2>Horas fuertes</h2><p>{stats.hours.slice().sort((a,b)=>b.qty-a.qty).slice(0,3).map(x=>`${x.hour} · ${x.qty.toFixed(1)} uds.`).join(' · ')||'Sin datos'}</p><em>Ver todas las horas ›</em></button></section>
  <section className="card productIntelSimulator"><div className="row between"><div><span className="sectionEyebrow">SIMULADOR DE DECISIONES</span><h2>Precio, coste e impacto</h2><p>El impacto matemático mantiene las mismas unidades vendidas. No se inventa una elasticidad de demanda.</p></div></div><div className="productIntelSimInputs"><label>Nuevo PVP<input type="number" inputMode="decimal" min="0" step="0.01" value={priceDraft} onChange={e=>setPriceDraft(e.target.value)}/></label><label>Nuevo coste €/ud<input type="number" inputMode="decimal" min="0" step="0.0001" value={costDraft} onChange={e=>setCostDraft(e.target.value)}/></label><label>Margen objetivo %<input type="number" inputMode="decimal" min="1" max="95" step="1" value={targetMargin} onChange={e=>setTargetMargin(e.target.value)}/></label></div><div className="grid productIntelSimulationKpis">{kpi('Beneficio simulado',money(simulatedProfit),`${impact>=0?'+':''}${money(impact)} vs actual`,[['Beneficio actual',money(currentProfit)],['Beneficio simulado',money(simulatedProfit)],['Impacto',money(impact)]])}{kpi('Margen simulado',`${simulatedMargin.toFixed(1)}%`,`Actual ${currentMargin.toFixed(1)}%`,[['Margen actual',`${currentMargin.toFixed(1)}%`],['Margen simulado',`${simulatedMargin.toFixed(1)}%`]])}{kpi('PVP para margen objetivo',money(targetPrice),`Objetivo ${target.toFixed(0)}%`,[['Coste simulado',money(newCost)],['Margen objetivo',`${target.toFixed(0)}%`],['PVP matemático',money(targetPrice)]])}{kpi('Ventas que podrías perder',`${maxLossPct.toFixed(1)}%`,'Y mantener el beneficio actual',[['Unidades actuales',stats.qty.toFixed(2)],['Unidades mínimas aprox.',breakEvenQty.toFixed(2)],['Pérdida máxima de volumen',`${maxLossPct.toFixed(1)}%`]])}</div><div className="productIntelActions"><button onClick={saveCost} disabled={saving||!selected.code}>{saving?'Guardando…':'Guardar nuevo coste'}</button><small>El PVP es solo una simulación: no se modifica automáticamente en Numier.</small></div></section>
  <button type="button" className="card productIntelAdvice" onClick={()=>open('Por qué el ERP recomienda esto',[['Unidades periodo',stats.qty.toFixed(2)],['Cambio unidades',`${qtyChange>=0?'+':''}${qtyChange.toFixed(1)}%`],['Margen actual',`${currentMargin.toFixed(1)}%`],['Coste usado',money(unitCost)],['Coste confirmado',configured?'Sí':'No']])}><span className="sectionEyebrow">ASESOR DE PRODUCTO</span><h2>🧠 Recomendación</h2><p>{recommendation}</p><em>Ver datos que sustentan la recomendación ›</em></button>
  <section className="card"><h2>🧩 Productos comprados junto a {selected.name}</h2><p className="mutedText">Detectados dentro de los mismos tickets del periodo.</p><div className="productIntelAssociated">{associated.map((p,i)=><button key={`${p.code}-${i}`} onClick={()=>{const id=p.code||`name:${norm(p.name)}`;setSelectedId(id);setQuery(p.name)}}><span><b>{p.name}</b><small>{p.ticketCount} tickets compartidos</small></span><strong>{p.qty.toFixed(1)} uds.</strong></button>)}{!associated.length&&<p>No hay suficientes coincidencias en este periodo.</p>}</div></section>
  </>}
  {detail&&<div className="modal productProfitOverlay" onClick={()=>setDetail(null)}><div className="card intelligenceModal productIntelModal" onClick={e=>e.stopPropagation()}><div className="row between"><div><span className="sectionEyebrow">DETALLE DE PRODUCTO</span><h2>{detail.title}</h2></div><button className="red" onClick={()=>setDetail(null)}>Cerrar</button></div><div className="profitDetailList">{(detail.rows||[]).map((r,i)=><p className="profitDetailRow" key={i}><span>{r[0]}</span><b>{r[1]}</b></p>)}</div></div></div>}
 </div>
}

'''
    app=app.replace(marker,component+marker,1)

style=r'''
/* COLIBRI ERP 5.3 - Inteligencia de Producto */
.productIntelligence53{display:grid;gap:16px}.productIntelSearch{display:grid;grid-template-columns:minmax(260px,1fr) minmax(300px,.8fr);gap:14px;align-items:end}.productIntelSearch h2,.productIntelHero h2,.productIntelSimulator h2,.productIntelAdvice h2{margin:.2rem 0}.productIntelSearch label{font-weight:900;color:#31475a}.productIntelResults{grid-column:1/-1;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px;max-height:240px;overflow:auto}.productIntelResults button{background:#f6fbfc;color:#263b4c;border:1px solid #d5e4e8;display:flex;justify-content:space-between;align-items:center;text-align:left}.productIntelResults button.active{background:#0b806f;color:#fff}.productIntelResults span,.productIntelResults small{display:block}.productIntelResults em{font-style:normal;font-weight:900;white-space:nowrap}.productIntelHero{display:flex;justify-content:space-between;gap:15px;align-items:center}.productIntelKpis{grid-template-columns:repeat(auto-fit,minmax(180px,1fr))}.productIntelKpi{width:100%;min-height:125px;text-align:left;background:#fff;color:#283b50;border:1px solid #dbe8ec;display:flex;flex-direction:column;justify-content:center}.productIntelKpi span{font-weight:900;color:#5a6c7d}.productIntelKpi b{font-size:1.7rem;color:#07876e;margin:.35rem 0}.productIntelKpi small{color:#607083}.productIntelChart{overflow:hidden}.productIntelBars{display:flex;align-items:flex-end;gap:8px;min-height:270px;overflow-x:auto;padding:18px 4px 4px}.productIntelBars button{background:transparent;color:#344a5e;min-width:58px;height:240px;padding:0;display:grid;grid-template-rows:24px 1fr 30px;align-items:end;text-align:center}.productIntelBars i{width:70%;justify-self:center;min-height:6px;border-radius:10px 10px 3px 3px;background:linear-gradient(180deg,#2aa9c8,#28b487)}.productIntelBars b{font-size:.78rem;white-space:nowrap}.productIntelCompare{grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}.productIntelDecisionCard,.productIntelAdvice{width:100%;text-align:left;background:#fff;color:#2a3e52;border:1px solid #d7e7eb}.productIntelDecisionCard em,.productIntelAdvice em{font-style:normal;color:#087e6c;font-weight:900}.productIntelSimulator{border:2px solid #c9eee5}.productIntelSimInputs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.productIntelSimInputs label{font-weight:900;color:#41556a}.productIntelSimulationKpis{grid-template-columns:repeat(auto-fit,minmax(190px,1fr));margin-top:14px}.productIntelActions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:12px}.productIntelActions small{color:#5e7182;font-weight:700}.productIntelAdvice{border-left:6px solid #16a085}.productIntelAssociated{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:8px}.productIntelAssociated button{background:#f5fbfa;color:#263c4e;border:1px solid #d7e8e5;display:flex;justify-content:space-between;align-items:center;text-align:left}.productIntelAssociated span,.productIntelAssociated small{display:block}.productIntelModal{max-width:760px;width:min(92vw,760px)}
@media(max-width:700px){.productIntelSearch{grid-template-columns:1fr}.productIntelResults{grid-column:auto;grid-template-columns:1fr;max-height:260px}.productIntelHero{display:block}.productIntelSimInputs{grid-template-columns:1fr}.productIntelBars{min-height:230px}.productIntelBars button{height:205px;min-width:52px}.productIntelKpi b{font-size:1.45rem}.productIntelActions{display:grid;grid-template-columns:1fr}.productIntelActions button{width:100%}.productIntelCompare,.productIntelAssociated{grid-template-columns:1fr}}
'''
if 'COLIBRI ERP 5.3 - Inteligencia de Producto' not in css:
    css += '\n'+style+'\n'

APP.write_text(app,encoding='utf-8')
CSS.write_text(css,encoding='utf-8')

for p in [Path('package.json'),Path('package-lock.json')]:
    if p.exists():
        s=p.read_text(encoding='utf-8')
        s=s.replace('"version": "5.2.0"','"version": "5.3.0"')
        p.write_text(s,encoding='utf-8')

print('COLIBRI ERP 5.3 source applied')
